import chisel3._
import chisel3.util._

sealed trait OscillatorType
object OscillatorType {
  case object Sine extends OscillatorType
  case object Square extends OscillatorType
  case object Saw extends OscillatorType
  case object Triangle extends OscillatorType
}

/**
  * Base class for all the oscillators that defines the interface and common parameters.
  * @param amp The amplitude of the wave generated by the oscillator. Must be non-negative and fit within the sample width.
  * @param sampleWid The number of bits in the output sample. Must be greater than 1.
  * @param phaseWid The number of bits in the phase accumulator. Must be greater than 2 to accommodate the triangle wave, which uses the MSB and next MSB for direction.
  */
abstract class BaseOscillator(
    amp: Int,
    sampleWid: Int,
    phaseWid: Int
) extends Module {
  val io = IO(new Bundle {
    // chisel hardware unsigned
    val increment = Input(
      UInt(phaseWid.W)
    ) // increment value for the phase accumulator, calculated from frequency and sample rate
    // neeeds to be signed
    val sample = Output(SInt(sampleWid.W)) // output sample, signed
  })
  // require non-neg values
  require(
    amp >= 0,
    "Amplitude must not be negative"
  ) // I allowed zero amplitude, which will just output a constant 0
  require(sampleWid > 1, "Sample width must be >1") // number of bits
  require(
    phaseWid > 2,
    "Phase width must be >2"
  ) // number of bits (needs to be >2 for triangle wave, which uses MSB and next MSB for direction)
  require(
    amp < (BigInt(1) << (sampleWid - 1)),
    "Amplitude must fit in signed sample width"
  ) // if sample width is 8 bits, max amplitude is 127, if sample width is 16 bits, max amplitude is 32767, etc.
  val increment = RegNext(io.increment)
}

/**
  * Square wave oscillator class that extends the BaseOscillator class. It generates a square wave by using an accumulator and selecting the output based on the MSB of the accumulator.
  *
  * @param amp The amplitude of the wave generated by the oscillator. Must be non-negative and fit within the sample width.
  * @param sampleWid The number of bits in the output sample. Must be greater than 1.
  * @param phaseWid The number of bits in the phase accumulator. Must be greater than 2.
  */
class SquareOscillator(
    amp: Int,
    sampleWid: Int,
    phaseWid: Int
) extends BaseOscillator(amp, sampleWid, phaseWid) { // class for an oscillator that uses an accumulator to generate a square wave

  // accumulator
  val acc = RegInit(0.U(phaseWid.W))
  // increment
  acc := acc + increment // overflow will wrap around

  // for square wave, just use MSB
  // if MSB is 1, output -amp
  // if MSB is 0, output +amp
  // that divides the phase in half
  io.sample := Mux(
    acc(phaseWid - 1),
    (-amp).S(sampleWid.W),
    (+amp).S(sampleWid.W)
  )
}

/**
 * Sawtooth oscillator class that extends the BaseOscillator class. It generates a sawtooth wave by using an accumulator and scaling the output to the desired amplitude.
 * @param amp The amplitude of the wave generated by the oscillator. Must be non-negative and fit within the sample width.
 * @param sampleWid The number of bits in the output sample. Must be greater than 1.
 * @param phaseWid The number of bits in the phase accumulator. Must be greater than 2.
 */
class SawOscillator(
    amp: Int,
    sampleWid: Int,
    phaseWid: Int
) extends BaseOscillator(amp, sampleWid, phaseWid) {
  // accumulator
  val acc = RegInit(0.U(phaseWid.W))
  // increment
  acc := acc + increment // overflow will wrap around

  // ramp is generated by taking all bits of acc except MSB
  // then mult by 2*amp and divide by 2^(phaseWid-1) to scale to desired amplitude8
  // then subtract amp to center around 0
  // accumulator gives linear ramp
  // io.sample := (acc(phaseWid - 2, 0) * (2 * amp).S(sampleWid.W)) / ((1 << (phaseWid - 1)) - 1).S(sampleWid.W) - amp.S(sampleWid.W)
  // exclude MSB for ramp values
  val ramp = acc

  // make sure calculated width is enough to hold the intermediate values
  val calcWid = phaseWid + sampleWid + 2
  // pad ramp with zeros to calcWid
  // val rampWide = ramp.pad(calcWid)
  // scale to 2*amp and divide by 2^(phaseWid-1) to scale to desired amp
  // sepated out for clarity
  val scale = (BigInt(2) * amp).U
  val denominator = (BigInt(1) << phaseWid) - 1

  val scaled = DivideByConstant(ramp * scale, denominator)
  // subtract amp to center around 0
  // zero extend amp to calcWid to match scaled width
  val centered = scaled.zext - amp.S(calcWid.W)

  io.sample := centered(sampleWid - 1, 0).asSInt
}

/**
 * Triangle wave oscillator class that extends the BaseOscillator class. It generates a triangle wave by using an accumulator and flipping the direction of the ramp based on the MSB of the accumulator.
 * @param amp The amplitude of the wave generated by the oscillator. Must be non-negative and fit within the sample width.
 * @param sampleWid The number of bits in the output sample. Must be greater than 1.
 * @param phaseWid The number of bits in the phase accumulator. Must be greater than 2.
 */
class TriangleOscillator(
    amp: Int,
    sampleWid: Int,
    phaseWid: Int
) extends BaseOscillator(amp, sampleWid, phaseWid) {

  // accumulator
  val acc = RegInit(0.U(phaseWid.W))
  // increment
  acc := acc + increment // overflow will wrap around

  // triangle wave is generated by taking all bits of acc except MSB
  // for linear output
  // XORing with MSB to flip direction for negative slope
  // then mult by 2*amp and divide by 2^(phaseWid-1) to scale to desired amplitude8
  // then subtract amp to center around 0
  // io.sample := ((acc(phaseWid - 2, 0) ^ Fill(phaseWid - 1, acc(phaseWid - 1))) * (2 * amp).S(sampleWid.W)) / ((1 << (phaseWid - 1)) - 1).S(sampleWid.W) - amp.S(sampleWid.W)
  // exclude MSB for ramp values
  val ramp = acc(phaseWid - 2, 0)

  // make sure calculated width is enough to hold the intermediate values
  val calcWid = phaseWid + sampleWid + 2
  // XOR with MSB to flip direction for negative slope
  val flipped = ramp ^ Fill(phaseWid - 1, acc(phaseWid - 1))
  // val flippedPad = flipped.pad(calcWid) // pad after flipping so the extra bits are not flipped
  // scale to 2*amp and divide by 2^(phaseWid-1) to scale to desired amp
  // separated out for clarity
  val scale = (BigInt(2) * amp).U
  val denominator = (BigInt(1) << (phaseWid - 1)) - 1

  val scaled = DivideByConstant(flipped * scale, denominator)

  // subtract amp to center around 0
  // zero extend amp to calcWid to match scaled width
  val centered = scaled.zext - amp.S(calcWid.W)

  // explicitly set width of output to sampleWid, since it is a signed value
  // use asSInt to convert to signed
  io.sample := centered(sampleWid - 1, 0).asSInt

}

/**
  * Sine wave oscillator class that extends the BaseOscillator class. It generates a sine wave by using a lookup table to map the phase accumulator to the corresponding sine value.
  * @param amp The amplitude of the wave generated by the oscillator. Must be non-negative and fit within the sample width.
  * @param sampleWid The number of bits in the output sample. Must be greater than 1.
  * @param phaseWid The number of bits in the phase accumulator. Must be greater than 2.
  */
class SineOscillator(
    amp: Int,
    sampleWid: Int,
    phaseWid: Int
) extends BaseOscillator(amp, sampleWid, phaseWid) {

  // sine wave needs lookup table
  // needs to be generated at elaboration time
  // VecInit used instead
  // sine tavle is 2^tableAddrWid entries, each entry is sampleWid bits
  // TODO: look at making table smaller by using symmetry and only storing 1/4 of the wave, then mirroring and inverting as needed
  // each entry is sampleWid bits
  val tableAddrWid = math.min(
    phaseWid,
    10
  ) // separate from phaseWid, so that table can be smaller than phase accumulator
  // max out at 10bit = 1024 entries
  // otherwise deualt would be 2^16=65k
  // changed to math.min so it is decided during elaboration instead of in hardware
  require(phaseWid >= tableAddrWid)
  val sineTable = VecInit(
    (0 until (1 << tableAddrWid)).map { i =>
      (Math.sin(2.0 * Math.PI * i / (1 << tableAddrWid)) * amp).toInt
        .S(sampleWid.W)
    }
  )
  // accumulator to index into sineTable
  val acc = RegInit(0.U(phaseWid.W))
  // increment
  acc := acc + increment // overflow will wrap around

  val idx = acc(
    phaseWid - 1,
    phaseWid - tableAddrWid
  ) // use MSBs of acc to index, since table is smaller than phase accumulator, so use MSBs to index into table

  // output sample from sineTable
  io.sample := sineTable(idx)
}

/**
  * Oscillator wrapper module that generates a waveform based on the specified oscillator type and parameters. It uses the appropriate oscillator class (Sine, Square, Saw, Triangle) to generate the waveform.
  *
  * @param oscType The type of oscillator to generate (Sine, Square, Saw, Triangle).
  * @param amp The amplitude of the wave generated by the oscillator. Must be non-negative and fit within the sample width.
  * @param sampleWid The number of bits in the output sample. Must be greater than 1.
  * @param phaseWid The number of bits in the phase accumulator. Must be greater than 2.
  * @param clkFreq The clock frequency in Hz to calculate increment for given frequency dynamically. clkFreq is assumed to be constant during elaboration, so the hardware can multiply by a constant to avoid division in the increment calculation.
  */
class Oscillator(
    oscType: OscillatorType, // type of oscillator to generate
    amp: Int, // the amplitude of the wave
    sampleWid: Int, // the number of bits in the output sample
    phaseWid: Int, // the number of bits in the phase accumulator
    clkFreq: Int =
      Nexys4.clockFrequency // clock freq in Hz to calculate increment for given frequency dynamically
) extends Module {
  val io = IO(new Bundle {
    val increment = Input(
      UInt(32.W)
    ) // frequency of the wave in Hz, for dynamic frequency control
    val valid = Output(
      Bool()
    ) // valid output to deal with invalid frequency inputs (0Hz or > Nyquist)
    val sample = Output(SInt(sampleWid.W)) // output sample, signed
  })

  // instantiate correct osc type
  val osc: BaseOscillator = oscType match {
    case OscillatorType.Sine =>
      Module(new SineOscillator(amp, sampleWid, phaseWid))
    case OscillatorType.Square =>
      Module(new SquareOscillator(amp, sampleWid, phaseWid))
    case OscillatorType.Saw =>
      Module(new SawOscillator(amp, sampleWid, phaseWid))
    case OscillatorType.Triangle =>
      Module(new TriangleOscillator(amp, sampleWid, phaseWid))
  }

  val increment = RegNext(io.increment)
  val validPitch =
    (increment > 0.U)

  // connect in and outs
  osc.io.increment := Mux(validPitch, increment, 0.U)
  io.sample := Mux(validPitch, osc.io.sample, 0.S)
  io.valid := validPitch
}
/**
  * PWM generator module that generates a PWM signal based on the input samples from multiple oscillators. It sums the input samples, normalizes them, and generates a PWM output based on the calculated duty cycle.
  *
  * @param sampleWid The number of bits in the input samples from the oscillators. Must be greater than 1.
  * @param numVoices The number of voices (oscillators) to sum and generate PWM for. Must be greater than 0.
  */
class PWMGenerator( // renamed to generator bc it uses the oscillator to generate a PWM signal
    sampleWid: Int = 8, // default to 8 bit
    numVoices: Int = 1 // default to 1 voice
) extends Module {
  require(sampleWid > 1, "Sample width must be >1") // number of bits
  require(numVoices > 0, "Number of voices must be >0") //

  val io = IO(new Bundle {
    val samples = Input(
      Vec(numVoices, SInt(sampleWid.W))
    ) // input samples from oscillators, signed
    val PWM_en = Input(Bool())
    val PWM_out = Output(Bool())
  })

 val voiceSamples = RegNext(io.samples)
  // convert signed sample to unsigned PWM threshold
  val sumWid = sampleWid + log2Ceil(numVoices) // +& adds 1 bit per tree level
  val sumSamples = Reg(SInt(sumWid.W))          // explicit width; RegNext would drop it
  sumSamples := voiceSamples.reduceTree(_ +& _) // sum all voices with carry to avoid overflow
  val finalSample=Wire(SInt(sampleWid.W))

  val sign=sumSamples < 0.S // get sign bit
  val mag=Mux(sign, -sumSamples, sumSamples).asUInt // get magnitude of sumSamples
  val quotient=DivideByConstant(mag,BigInt(numVoices)).zext // divide by number of voices to normalize
  finalSample:=Mux(sign, -quotient, quotient) // restore sign to normalized value
  
  val pwmThres =finalSample.asUInt ^ (BigInt(1) << (sampleWid - 1)).U(sampleWid.W) // convert signed to unsigned by adding 2^(sampleWid-1) to shift range from [-amp, amp] to [0, 2*amp]
  // XOR with sign bit (MSB) is equivalent but cheaper

  // carrier counter for PWM
  // does not depend on frequency
  val pwmCounter = RegInit(0.U(sampleWid.W))
  pwmCounter := pwmCounter + 1.U

  val duty = RegInit(0.U(sampleWid.W))

  when(pwmCounter.andR) // keep duty cycle constant until counter wraps around
  {
    duty := Mux(
      io.PWM_en,
      pwmThres,
      0.U
    ) // update duty cycle only if PWM_en is high
  }

  // mux to enable/disable PWM output
  // output value
  io.PWM_out := io.PWM_en && (pwmCounter < duty) // only outputs when PWM_en is high, otherwise output 0
}
